/*
 * Modified by Actuna Sp. z o.o.:
 *   Z-02: httpAdminNodeRoutes - admin routes of nodes and plugins without an explicit
 *   permission require authentication in "authenticated" mode; RED.auth.publicRoute()
 *   Z-02: the permission marker must come before the first handler of a route;
 *   use() without a path is skipped for a request without authentication;
 *   limitations of the guard documented
 * This notice is required by section 4(b) of the Apache License 2.0.
 */

const path = require("path");
const http = require("http");
const semver = require("semver");
const url = require("url");
const {events,i18n,log} = require("@node-red/util");

var runtime;

// Marker set by RED.auth.needsPermission()/RED.auth.publicRoute() on the
// middleware they return. Uses the global symbol registry so the registry
// does not depend on @node-red/editor-api.
const ADMIN_ROUTE_AUTH = Symbol.for("node-red.adminRouteAuth");
const ADMIN_APP_METHODS = http.METHODS.map(m => m.toLowerCase()).concat(["all"]);
let adminNodeRoutesWarned = {};

function passThroughMiddleware() {
    return function(req,res,next) { next() }
}
function publicRouteFallback() {
    const middleware = passThroughMiddleware();
    middleware[ADMIN_ROUTE_AUTH] = "public";
    return middleware;
}

/**
 * Get the mode of the httpAdminNodeRoutes setting.
 * Logs a warning (once) for an unknown value, which is treated as "authenticated",
 * and for "authenticated" without adminAuth, which has no effect.
 * @return {String} "open" | "authenticated"
 */
function getAdminNodeRoutesMode() {
    const settings = runtime.settings || {};
    const value = settings.httpAdminNodeRoutes;
    if (value === undefined || value === null || value === "open") {
        return "open";
    }
    if (value !== "authenticated" && !adminNodeRoutesWarned.unknown) {
        adminNodeRoutesWarned.unknown = true;
        log.warn(log._("server.admin-node-routes.unknown-value", {value: String(value)}));
    }
    if (!settings.adminAuth) {
        if (!adminNodeRoutesWarned.noAdminAuth) {
            adminNodeRoutesWarned.noAdminAuth = true;
            log.warn(log._("server.admin-node-routes.no-admin-auth"));
        }
        return "open";
    }
    return "authenticated";
}

/**
 * Gets the authentication marker of the handlers of an admin route.
 * A needsPermission() marker counts only when it comes before the first
 * handler without a marker (D1): in get(path, handler, needsPermission(x))
 * the handler would run before the check. A publicRoute() marker may be
 * anywhere, as it does not check anything.
 * @return {String|null} "permission" | "public" | null
 */
function getRouteMarker(handlers) {
    const flat = handlers.flat(Infinity);
    let leading = true;
    let isPublic = false;
    for (let i = 0; i < flat.length; i++) {
        const marker = typeof flat[i] === "function" ? flat[i][ADMIN_ROUTE_AUTH] : undefined;
        if (!marker) {
            leading = false;
        } else if (marker === "permission" && leading) {
            return "permission";
        } else if (marker === "public") {
            isPublic = true;
        }
    }
    return isPublic ? "public" : null;
}

/**
 * Prepares the handlers of an admin route registered by a node or plugin.
 * Handlers starting with a needsPermission() middleware are left unchanged,
 * a route marked by publicRoute() is logged, any other route gets
 * needsPermission("") prepended.
 */
function guardHandlers(auth, owner, method, path, handlers) {
    const marker = getRouteMarker(handlers);
    if (marker === "public") {
        log.info(log._("server.admin-node-routes.public-route", {
            module: owner,
            method: method.toUpperCase(),
            path: path === undefined ? "/" : String(path)
        }));
        return handlers;
    } else if (marker === "permission") {
        return handlers;
    }
    return [auth.needsPermission("")].concat(handlers);
}

// Response methods that send a response: when the permission check calls
// one of them, the request is not authenticated
const RESPONSE_SEND_METHODS = ["end","write","send","json","jsonp","sendStatus","sendFile","download","redirect","render"];
// Response methods that only change the response before it is sent
const RESPONSE_SET_METHODS = ["status","set","header","setHeader","writeHead","append","type","vary","location","links","cookie","clearCookie","removeHeader","attachment","format"];

/**
 * Runs the needsPermission("") check of the admin api without sending its
 * response. The result is kept on the request, so the check runs once per
 * request for all handlers of one use() call.
 * @param {Function} check - the needsPermission("") middleware
 * @param {Symbol} key - the request property for the result
 * @param {Function} done - called with (err, allowed)
 */
function checkAuthenticated(check, key, req, res, done) {
    if (req[key] !== undefined) {
        return done(null, req[key]);
    }
    let settled = false;
    const probe = Object.create(res);
    const deny = function() {
        if (!settled) {
            settled = true;
            req[key] = false;
            done(null, false);
        }
        return probe;
    };
    const keep = function() { return probe };
    RESPONSE_SEND_METHODS.forEach(function(m) { probe[m] = deny });
    RESPONSE_SET_METHODS.forEach(function(m) { probe[m] = keep });
    check(req, probe, function(err) {
        if (settled) {
            return;
        }
        settled = true;
        if (err) {
            return done(err);
        }
        req[key] = true;
        done(null, true);
    });
}

/**
 * Wraps the handlers of a use() call without a path (or with path "/"), which
 * applies to every admin request, including routes of other modules. A
 * request without authentication skips these handlers (W1), instead of
 * getting 401 for every later route; an authenticated request runs them.
 * Error handlers keep their arity and express sub-applications are mounted
 * as app.use() does.
 */
function guardGlobalHandlers(app, auth, handlers) {
    const check = auth.needsPermission("");
    const key = Symbol("adminRouteAuthenticated");
    return handlers.flat(Infinity).map(function(fn) {
        if (typeof fn !== "function") {
            return fn;
        }
        if (fn.length === 4) {
            return function(err, req, res, next) {
                checkAuthenticated(check, key, req, res, function(checkErr, allowed) {
                    if (checkErr || !allowed) {
                        return next(err);
                    }
                    fn(err, req, res, next);
                });
            };
        }
        let handle = fn;
        if (typeof fn.handle === "function" && typeof fn.set === "function") {
            // An express sub-application: same as the mounted_app wrapper of app.use()
            fn.mountpath = "/";
            fn.parent = app;
            handle = function(req, res, next) {
                const orig = req.app;
                fn.handle(req, res, function(err) {
                    Object.setPrototypeOf(req, orig.request);
                    Object.setPrototypeOf(res, orig.response);
                    next(err);
                });
            };
            if (typeof fn.emit === "function") {
                fn.emit("mount", app);
            }
        }
        return function(req, res, next) {
            checkAuthenticated(check, key, req, res, function(err, allowed) {
                if (err) {
                    return next(err);
                }
                if (!allowed) {
                    return next();
                }
                handle(req, res, next);
            });
        };
    });
}

function isPathArgument(arg) {
    return typeof arg === "string" || arg instanceof RegExp ||
        (Array.isArray(arg) && arg.length > 0 && arg.every(a => typeof a === "string" || a instanceof RegExp));
}

/**
 * Wraps the admin express app given to a node or plugin so that every route
 * registered through it without needsPermission() or publicRoute() requires
 * an authenticated user (or the default user, as needsPermission("")).
 * Routes are still added to the original app.
 *
 * Limitations (D2): this is a safer default for well-behaved nodes, not a
 * sandbox. Node code can still add a route without the guard through the
 * internal router (`RED.httpAdmin._router`), the prototype of the guarded
 * object (`Object.getPrototypeOf(RED.httpAdmin)`), `app.param()` handlers
 * (inherited, not guarded) or `require('node-red').httpAdmin`.
 * @param {Object} app - the runtime admin express app
 * @param {Object} auth - the admin auth api ({needsPermission})
 * @param {String} owner - the module registering routes, used in the log
 * @return {Object} the guarded app
 */
function guardAdminApp(app, auth, owner) {
    if (typeof app.lazyrouter === "function") {
        // Create the router on the original app, so inherited methods
        // (such as param) do not create one on the guarded object
        app.lazyrouter();
    }
    const guarded = Object.create(app);
    ADMIN_APP_METHODS.forEach(function(method) {
        if (typeof app[method] !== "function") {
            return;
        }
        guarded[method] = function(path) {
            if (method === "get" && arguments.length === 1) {
                // app.get(setting)
                return app.get(path);
            }
            const handlers = Array.prototype.slice.call(arguments, 1);
            app[method].apply(app, [path].concat(guardHandlers(auth, owner, method, path, handlers)));
            return guarded;
        }
    });
    guarded.use = function() {
        const args = Array.prototype.slice.call(arguments);
        let path;
        if (isPathArgument(args[0])) {
            path = args.shift();
        }
        if ((path === undefined || path === "/") && getRouteMarker(args) === null) {
            const handlers = guardGlobalHandlers(app, auth, args);
            app.use.apply(app, path === undefined ? handlers : [path].concat(handlers));
            return guarded;
        }
        const handlers = guardHandlers(auth, owner, "use", path, args);
        app.use.apply(app, path === undefined ? handlers : [path].concat(handlers));
        return guarded;
    }
    guarded.route = function(path) {
        const route = app.route(path);
        const guardedRoute = Object.create(route);
        ADMIN_APP_METHODS.forEach(function(method) {
            if (typeof route[method] !== "function") {
                return;
            }
            guardedRoute[method] = function() {
                const handlers = Array.prototype.slice.call(arguments);
                route[method].apply(route, guardHandlers(auth, owner, method, path, handlers));
                return guardedRoute;
            }
        });
        return guardedRoute;
    }
    return guarded;
}

function copyObjectProperties(src,dst,copyList,blockList) {
    if (!src) {
        return;
    }
    if (copyList && !blockList) {
        copyList.forEach(function(i) {
            if (src.hasOwnProperty(i)) {
                var propDescriptor = Object.getOwnPropertyDescriptor(src,i);
                Object.defineProperty(dst,i,propDescriptor);
            }
        });
    } else if (!copyList && blockList) {
        for (var i in src) {
            if (src.hasOwnProperty(i) && blockList.indexOf(i) === -1) {
                var propDescriptor = Object.getOwnPropertyDescriptor(src,i);
                Object.defineProperty(dst,i,propDescriptor);
            }
        }
    }
}
function requireModule(name) {
    var moduleInfo = require("./index").getModuleInfo(name);
    if (moduleInfo && moduleInfo.path) {
        var relPath = path.relative(__dirname, moduleInfo.path);
        return require(relPath);
    } else {
        // Require it here to avoid the circular dependency
        return require("./externalModules").require(name);
    }
}
function importModule(name) {
    var moduleInfo = require("./index").getModuleInfo(name);
    if (moduleInfo && moduleInfo.path) {
        const moduleFile = url.pathToFileURL(require.resolve(moduleInfo.path));
        return import(moduleFile);
    } else {
        // Require it here to avoid the circular dependency
        return require("./externalModules").import(name);
    }
}

function createNodeApi(node) {
    var red = {
        nodes: {},
        log: {},
        settings: {},
        events: events,
        hooks: runtime.hooks,
        util: runtime.util,
        version: runtime.version,
        require: requireModule,
        import: importModule,
        comms: {
            publish: function(topic,data,retain) {
                events.emit("comms",{
                    topic: topic,
                    data: data,
                    retain: retain
                })
            }
        },
        plugins: {
            registerPlugin: function(id,definition) {
                return runtime.plugins.registerPlugin(node.id,id,definition);
            },
            get: function(id) {
                return runtime.plugins.getPlugin(id);
            },
            getByType: function(type) {
                return runtime.plugins.getPluginsByType(type);
            }
        },
        library: {
            register: function(type) {
                return runtime.library.register(node.id,type);
            }
        },
        httpNode: runtime.nodeApp,
        httpAdmin: runtime.adminApp,
        server: runtime.server
    }
    copyObjectProperties(runtime.nodes,red.nodes,["createNode","getNode","eachNode","addCredentials","getCredentials","deleteCredentials"]);
    red.nodes.registerType = function(type,constructor,opts) {
        runtime.nodes.registerType(node.id,type,constructor,opts);
    }
    red.nodes.registerSubflow = function(subflowDef) {
        runtime.nodes.registerSubflow(node.id,subflowDef)
    }
    copyObjectProperties(log,red.log,null,["init"]);
    copyObjectProperties(runtime.settings,red.settings,null,["init","load","reset"]);
    if (runtime.adminApi) {
        red.auth = runtime.adminApi.auth;
    } else {
        //TODO: runtime.adminApi is always stubbed if not enabled, so this block
        // is unused - but may be needed for the unit tests
        red.auth = {
            needsPermission: function(v) { return passThroughMiddleware() },
            publicRoute: publicRouteFallback
        };
        // TODO: stub out httpAdmin/httpNode/server
    }
    if (red.auth && !red.auth.publicRoute) {
        // An embedding application may provide its own admin api
        red.auth = Object.assign({}, red.auth, { publicRoute: publicRouteFallback });
    }
    if (red.httpAdmin && runtime.adminApi && getAdminNodeRoutesMode() === "authenticated") {
        red.httpAdmin = guardAdminApp(red.httpAdmin, red.auth, node.module || node.id);
    }
    red["_"] = function() {
        var args = Array.prototype.slice.call(arguments, 0);
        if (args[0].indexOf(":") === -1) {
            args[0] = node.namespace+":"+args[0];
        }
        return i18n._.apply(null,args);
    }
    red.nodes.linkcallTargets = runtime.nodes.linkcallTargets;
    return red;
}


function checkAgainstList(module,version,list) {
    for (let i=0;i<list.length;i++) {
        let rule = list[i];
        if (rule.module.test(module)) {
            if (version && rule.version) {
                if (semver.satisfies(version,rule.version)) {
                    return rule;
                }
            } else {
                return rule;
            }
        }
    }
}

function checkModuleAllowed(module,version,allowList,denyList) {
    if (!allowList && !denyList) {
        // Default to allow
        return true;
    }
    if (allowList.length === 0 && denyList.length === 0) {
        return true;
    }

    var allowedRule = checkAgainstList(module,version,allowList);
    var deniedRule = checkAgainstList(module,version,denyList);
    // console.log("A",allowedRule)
    // console.log("D",deniedRule)

    if (allowedRule && !deniedRule) {
        return true;
    }
    if (!allowedRule && deniedRule) {
        return false;
    }
    if (!allowedRule && !deniedRule) {
        return true;
    }
    if (allowedRule.wildcardPos !== deniedRule.wildcardPos) {
        return allowedRule.wildcardPos > deniedRule.wildcardPos
    } else {
        // First wildcard in same position.
        // Go with the longer matching rule. This isn't going to be 100%
        // right, but we are deep into edge cases at this point.
        return allowedRule.module.toString().length > deniedRule.module.toString().length
    }
    return false;
}

function parseModuleList(list) {
    list = list || ["*"];
    return list.map(rule => {
        let m = /^(.+?)(?:@(.*))?$/.exec(rule);
        let wildcardPos = m[1].indexOf("*");
        wildcardPos = wildcardPos===-1?Infinity:wildcardPos;

        return {
            module: new RegExp("^"+m[1].replace(/\*/g,".*")+"$"),
            version: m[2],
            wildcardPos: wildcardPos
        }
    })
}


module.exports = {
    init: function(_runtime) {
        runtime = _runtime;
        adminNodeRoutesWarned = {};
    },
    createNodeApi: createNodeApi,
    parseModuleList: parseModuleList,
    checkModuleAllowed: checkModuleAllowed
}
